package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext by removing spaces and punctuation and
// down-casing it, organizes the result into a rectangle as square as
// possible, and returns the rectangle read down the columns: c chunks of r
// characters each, separated by single spaces. Chunks that are short of a
// full column are padded with trailing spaces.
func Encode(pt string) string {
	// Normalize: keep only letters and digits, lower-cased.
	var normalized []rune
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			normalized = append(normalized, unicode.ToLower(r))
		}
	}
	n := len(normalized)
	if n == 0 {
		return ""
	}

	// Rectangle dimensions: smallest c with c >= r, c-r <= 1 and r*c >= n.
	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	// Pad so the rectangle is complete.
	padded := make([]rune, r*c)
	copy(padded, normalized)
	for i := n; i < r*c; i++ {
		padded[i] = ' '
	}

	// Read down the columns, left to right.
	var sb strings.Builder
	sb.Grow(r*c + c - 1)
	for j := 0; j < c; j++ {
		if j > 0 {
			sb.WriteByte(' ')
		}
		for i := 0; i < r; i++ {
			sb.WriteRune(padded[i*c+j])
		}
	}
	return sb.String()
}

